/**
 * Request bodies of the admin account routes (dispatch 38). Strict: a body
 * carrying anything else is refused, not trimmed. PINs are generated by Nubnb
 * (Kian's ruling of 2026-10-13, evening), so no body carries a new PIN; the
 * one that carries a current PIN is never logged or echoed.
 */

import { z } from 'zod';
import { ADMIN_LEVELS, adminNameProblem, cleanAdminName } from './model';

const name = z
  .string()
  .max(500)
  .superRefine((value, ctx) => {
    const problem = adminNameProblem(value);
    if (problem) ctx.addIssue({ code: 'custom', message: problem });
  })
  .transform(cleanAdminName);

/** Adding an admin: their name and level. The PIN is generated, and shown once in the answer. */
export const NewAdminSchema = z.strictObject({
  name,
  level: z.enum(ADMIN_LEVELS),
});

export const SetLevelSchema = z.strictObject({ level: z.enum(ADMIN_LEVELS) });

/** Change name, from an admin's own menu. */
export const ChangeNameSchema = z.strictObject({ name });

/** New PIN, from an admin's own menu: the current PIN first. */
export const RenewPinSchema = z.strictObject({ currentPin: z.string().max(20) });
